          emfLog(
            `  Deferred image [${idx}]: creating ImageBitmap from ${metaBlob.size} byte blob (${mime})...`
          );
          const bitmap = await createImageBitmap(metaBlob);
          emfLog(`  Deferred image [${idx}]: ImageBitmap created ${bitmap.width}\xD7${bitmap.height}`);
